+			  VALS(ws_ovs_meter_band_type_vals), 0x00,
+			  NULL, HFILL }
+		},
+		{ &hf_ovs_meter_band_rate,
+			{ "Band rate", "ovs_meter.band.rate",
+			  FT_UINT32, BASE_DEC, NULL, 0x00, NULL, HFILL }
+		},
